import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({ base: './', plugins: [vue()] })

import { createRouter, createWebHashHistory } from 'vue-router'
import PortalView from '../views/PortalView.vue'
import ArticleView from '../views/ArticleView.vue'

export default createRouter({
  history: createWebHashHistory(),
  routes: [
    { path: '/', component: PortalView },
    { path: '/article/:slug', component: ArticleView }
  ]
})

:root { font-family: Georgia, 'Noto Serif SC', serif; color: #24231f; background: #fcfbf7; }
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; text-decoration: none; }
header { height: 82px; display: flex; align-items: center; padding: 0 max(24px, calc((100% - 1080px) / 2)); border-bottom: 1px solid #dcd8cd; gap: 36px; }
.logo { font-size: 25px; font-weight: 800; letter-spacing: .08em; margin-right: auto; }
nav { display: flex; gap: 28px; }
button { border: 1px solid #24231f; background: transparent; padding: 9px 16px; }
main { width: min(1080px, calc(100% - 40px)); margin: 0 auto; }
.issue { margin: 34px 0 18px; color: #857d70; }
.lead { display: grid; grid-template-columns: 1.3fr 1fr; background: #e7e0d1; }
.lead-image { min-height: 410px; display: grid; place-items: center; background: #52655a; color: #e9eee8; font-size: 45px; letter-spacing: .2em; }
.lead section { padding: 60px 50px; }
h1 { font-size: clamp(2.4rem, 5vw, 4rem); line-height: 1.14; margin: 15px 0 22px; }
p { color: #625e56; line-height: 1.85; }
.section-title { display: flex; align-items: end; justify-content: space-between; margin: 64px 0 22px; border-bottom: 2px solid #24231f; }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 25px; padding-bottom: 72px; }
.picture { aspect-ratio: 4/3; display: grid; place-items: center; margin-bottom: 18px; color: #fff; background: #8b6d58; font-size: 30px; }
.cards h3 { font-size: 23px; margin: 8px 0; }
.article { width: min(720px, calc(100% - 40px)); margin: 80px auto; font-size: 18px; }
.intro { font-size: 22px; }
.article-image { min-height: 330px; display: grid; place-items: center; margin: 40px -100px; background: #52655a; color: #fff; font-size: 26px; }
blockquote { margin: 35px 0; padding-left: 24px; border-left: 4px solid #bd5a3f; font-size: 24px; line-height: 1.6; }
footer { padding: 36px; text-align: center; border-top: 1px solid #dcd8cd; color: #857d70; }
@media (max-width: 760px) { nav { display: none; } .lead, .cards { grid-template-columns: 1fr; } .lead section { padding: 34px; } .article-image { margin: 30px 0; } }
